<?php if($source):?>
<section class="card"><h2><?=access_h(cd_source_label($source['type']))?> #<?=(int)$source['id']?></h2><div class="finance-grid"><?php foreach(['amount'=>'Amount Under Review','verified'=>'Currently Verified','returned'=>'Returned To Custody','remaining'=>'Unresolved / Awaiting Verification'] as $key=>$label):if($key==='returned'&&!in_array($source['type'],['deposit','handover'],true))continue;?><p><?=access_h($label)?> <strong><?=access_h(cd_money($source[$key]))?></strong></p><?php endforeach?></div><p>Original activity <?=access_h(display_date($source['row']['created_at']))?> UTC · Retained Reference <?=access_h($source['reference']?:'Not Recorded')?></p><?php if(in_array($source['type'],['deposit','handover'],true)):?><p>Cash receipts retain their full original next-day deposit obligation. Returned cash is due for deposit; no new receipt, revenue, expense or refund is created here.</p><?php else:?><p>The recorded receipt remains unchanged. Unverified wallet credit stays under review; any receipt correction or actual recovery is a separate linked action.</p><?php endif?><?php if($source['fee']):?><p class="notice">This existing deposit includes a fee. Report and follow up here; partial credit, return and reversal posting requires separately supported fee reconciliation.</p><?php endif?></section>
<?php if($source['type']==='payment'&&($source['current_method']??'momo')!=='momo'):?><p class="notice">This receipt is currently recorded as Cash. Its previous wallet proof and correction history remain linked here. No wallet amount is due on this receipt.</p><?php endif?>
<?php if(!$case):?>
<section class="card" id="discrepancy-action" tabindex="-1"><h2>Report Difference</h2><form method="post" enctype="multipart/form-data" data-cd-form><?php cd_fields('report');?><label>Difference Type *<select name="category" required><?php foreach(['short'=>'Short Credit / Amount Disputed','delayed'=>'Credit Delayed','failed'=>'Failed Transfer','reversed'=>'Reversed Credit','disputed'=>'Other Dispute'] as $key=>$label):?><option value="<?=$key?>" <?=cd_value('category')===$key?'selected':''?>><?=$label?></option><?php endforeach?></select></label><?php cd_reason('Describe Difference');cd_upload();?><div class="finance-actions"><button>Report Difference</button><a href="<?=access_h(cd_url())?>">Cancel</a></div></form></section>
