<?php $actions=[];if($owner){if($source['type']!=='handover'&&$source['remaining']>0)$actions['credit']='Record Verified Wallet Credit';if($source['type']!=='handover'&&$source['verified']>0)$actions['reverse']='Record Reversed / Disputed Credit';if(in_array($source['type'],['deposit','handover'],true)&&$source['remaining']>0)$actions['return_cash']='Record Actual Cash Returned';if(!$source['remaining'])$actions['confirm_evidence']='Confirm Existing Evidence';}if($source['type']==='handover'&&$source['recipient']===$actor&&$source['remaining']>0)$actions['acknowledge']='Acknowledge Cash Actually Received';$actions['followup']='Add Follow-Up';$actions['reopen']='Report New / Reopened Dispute';?>
<section class="card" id="discrepancy-action" tabindex="-1"><h2>Record Next Action</h2><form method="post" enctype="multipart/form-data" data-cd-form data-total="<?=$source['amount']?>" data-verified="<?=$source['verified']?>" data-returned="<?=$source['returned']?>" data-type="<?=access_h($source['type'])?>"><?php cd_fields('followup');?><label>Action *<select name="decision" data-cd-action><?php foreach($actions as $key=>$label):?><option value="<?=$key?>" <?=cd_value('action',array_key_first($actions))===$key?'selected':''?>><?=$label?></option><?php endforeach?></select></label><label data-cd-amount>Amount For This Action (GHS) *<input name="amount" inputmode="decimal" maxlength="16" value="<?=access_h(cd_value('amount',\Tivoli\Domain\Stay\StayRules::decimal($source['remaining']?:$source['verified'])))?>"></label><label data-cd-reference>Independent Evidence / Transaction Reference *<input name="reference" maxlength="120" value="<?=access_h(cd_value('reference'))?>"></label><?php cd_reason();cd_upload();if($owner):?><div data-cd-assignment hidden><label>Accountable Person (Optional)<select name="assignee_id"><option value="">Keep Existing Responsibility</option><?php foreach(access_service()->repo->run('SELECT u.id,u.name FROM users u JOIN security_accounts a ON a.user_id=u.id WHERE a.active=1 AND u.id IN (?,?,?) ORDER BY u.name,u.id',[$actor,$source['origin'],$source['recipient']??0])->fetchAll() as $person):?><option value="<?=(int)$person['id']?>"><?=access_h($person['name'])?></option><?php endforeach?></select></label><label>Follow-Up Due Date (Optional)<input type="date" name="due" value="<?=access_h(cd_value('due'))?>"></label></div><?php endif?><p data-cd-preview role="status"></p><label class="finance-check" data-cd-check><input type="checkbox" name="verified" value="1"> I verified these facts against independent evidence, or personally received the cash as the named recipient.</label><p><?php if(in_array($source['type'],['deposit','handover'],true)):?>Cash returns require evidence of actual return to the original custodian. <?php endif?>This records completed facts; it does not initiate a transfer.</p><div class="finance-actions"><button>Record Action</button><a href="<?=access_h(cd_url(['id'=>$caseId]))?>#discrepancy-action">Cancel</a></div></form></section>
<section class="card"><h2>Retained History</h2><?php foreach(array_merge([$case['root']],$case['history']) as $event):?><article><h3><?=access_h(cd_event_label($event['kind']))?> · #<?=(int)$event['id']?></h3><p><?=access_h($event['actor_name'].' · '.display_date($event['created_at']))?> UTC · <?=access_h(cd_money((int)$event['amount_minor']))?></p><p><?=access_h($event['data']['reason']??'')?></p><?php if(!empty($event['data']['assignee_name'])):?><p>Accountable: <?=access_h($event['data']['assignee_name'])?></p><?php endif?><?php if(!empty($event['data']['due'])):?><p>Due: <?=access_h(display_date($event['data']['due']))?> UTC</p><?php endif?><?php if(!empty($event['data']['reference'])):?><p>Evidence reference <?=access_h($event['data']['reference'])?></p><?php endif?><?php if(\Tivoli\Service\FinanceAttachment::available(access_service(),'cashdiscrepancy',(int)$event['id'])):?><a href="<?=access_h(access_url('finance-evidence.php?kind=cashdiscrepancy&id='.$event['id']))?>">Download Private Evidence</a><?php endif?></article><?php endforeach?></section>
<?php endif?>
<?php else:?>
<section class="card"><h2><?=$owner?'Owner Review Queue':'My Linked Cases'?></h2><p>Start from Report Difference beside a deposit, unmatched MoMo receipt or cash handover. Cases remain visible after financial period closure.</p><?php foreach($rows as $row):?><article><h3><?=access_h(cd_source_label($row['source']['type']))?> #<?=(int)$row['source']['id']?> · <?=access_h(ucwords(str_replace('_',' ',$row['status'])))?></h3><p><?=access_h(cd_money($row['source']['remaining']))?> unresolved · <?=access_h($row['root']['actor_name'])?></p><a class="finance-action" href="<?=access_h(cd_url(['id'=>$row['root']['id']]))?>#discrepancy-action">Show Details</a></article><?php endforeach;if(!$rows):?><p>No visible discrepancy cases.</p><?php endif?><?php if($next):?><a href="<?=access_h(cd_url(['before'=>$next]))?>">Older Cases</a><?php endif?></section>
